questions.solution:
#include <stdio.h>

int main() {
    int arr[5];
    int i;
    int largest;

    /* Read 5 integers from user */
    printf("Enter 5 integers:\n");
    for (i = 0; i < 5; i++) {
        scanf("%d", &arr[i]);
    }

    /* Find the largest element */
    largest = arr[0];  /* assume first is largest */
    for (i = 1; i < 5; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    printf("Largest = %d\n", largest);
    return 0;
}
